def main():
    while True:
        try:
            line = input()
        except EOFError:
            break
        if line.strip() == "quit":
            print("До встречи!")
            break
        print("команда:", line)

def cmd_hello(args):
    return "Привет, " + (" ".join(args) or "мир")


def cmd_sum(args):
    return str(sum(float(a) for a in args))


COMMANDS = {"hello": cmd_hello, "sum": cmd_sum}
